    if (count != 2) return error.InvalidInput;

    const row = numbers[0];
    const col = numbers[1];
    if (row == 0 or col == 0) return error.InvalidCoordinates;

    const diagonal: u128 = @as(u128, row) + @as(u128, col) - 1;
    const steps = diagonal * (diagonal - 1) / 2 + (@as(u128, col) - 1);

    const modulus: u64 = 33554393;
    const code = (20151125 * modPow(252533, steps, modulus)) % modulus;

    const stdout = std.io.getStdOut().writer();
    try stdout.print("{d}\n", .{code});
}
